124	    DataTypePtr getDataTypeFromFieldImpl(const Element & field)
125	    {
126	        if (field.isNull())
127	            return nullptr;
128	
129	        if (field.isBool())
130	            return DataTypeFactory::instance().get("Nullable(Bool)");
131	
132	        if (field.isInt64() || field.isUInt64() || field.isDouble())
133	            return makeNullable(std::make_shared<DataTypeFloat64>());
134	
135	        if (field.isString())
136	            return makeNullable(std::make_shared<DataTypeString>());
137	
138	        if (field.isArray())
139	        {
140	            auto array = field.getArray();
141	
142	            /// Return nullptr in case of empty array because we cannot determine nested type.
143	            if (array.size() == 0)
144	                return nullptr;
145	
146	            DataTypes nested_data_types;
147	            /// If this array contains fields with different types we will treat it as Tuple.
148	            bool is_tuple = false;
149	            for (const auto element : array)
150	            {
151	                auto type = getDataTypeFromFieldImpl(element);
152	                if (!type)
153	                    return nullptr;
154	
155	                if (!nested_data_types.empty() && type->getName() != nested_data_types.back()->getName())
156	                    is_tuple = true;
157	
158	                nested_data_types.push_back(std::move(type));
159	            }
160	
161	            if (is_tuple)
162	                return std::make_shared<DataTypeTuple>(nested_data_types);
163	
164	            return std::make_shared<DataTypeArray>(nested_data_types.back());
165	        }
166	
167	        if (field.isObject())
168	        {
169	            auto object = field.getObject();
170	            DataTypePtr value_type;
171	            bool is_object = false;
172	            for (const auto key_value_pair : object)
173	            {
174	                auto type = getDataTypeFromFieldImpl(key_value_pair.second);
175	                if (!type)
176	                    continue;
177	
178	                if (isObject(type))
179	                {
180	                    is_object = true;
181	                    break;
182	                }
183	
184	                if (!value_type)
185	                {
186	                    value_type = type;
187	                }
188	                else if (!value_type->equals(*type))
189	                {
190	                    is_object = true;
191	                    break;
192	                }
193	            }
194	
195	            if (is_object)
196	                return std::make_shared<DataTypeObject>("json", true);
197	
198	            if (value_type)
199	                return std::make_shared<DataTypeMap>(std::make_shared<DataTypeString>(), value_type);
200	
201	            return nullptr;
202	        }
203	
204	        throw Exception{ErrorCodes::INCORRECT_DATA, "Unexpected JSON type"};
